// Writes tests/reference.txt: cases over every byte value, with the expected
// results computed by the Rust standard library (formatting with `{:02x}`,
// `{:02X}` and `{:?}`, parsing with `u8::from_str_radix`), not by the port.
// The Debug text of a char depends on the Rust version's Unicode tables; the
// file was written with the rustc version named in its header.
//
//     rustc -O tests/reference.rs -o /tmp/reference && /tmp/reference > tests/reference.txt

fn esc(bytes: &[u8]) -> String {
    let mut s = String::new();
    for &b in bytes {
        match b {
            b'\\' => s.push_str("\\\\"),
            b'|' => s.push_str("\\x7c"),
            0x20..=0x7e => s.push(b as char),
            _ => s.push_str(&format!("\\x{:02x}", b)),
        }
    }
    s
}

fn case(op: &str, input: &[u8], expected: &[u8]) {
    println!("{}|{}|{}", op, esc(input), esc(expected));
}

fn is_digit(b: u8) -> bool {
    b.is_ascii_hexdigit()
}

fn main() {
    let version = std::env::var("RUSTC_VERSION").unwrap_or_default();
    println!("# Generated by tests/reference.rs ({}). Same format as cases.txt.", version.trim());
    let all: Vec<u8> = (0..=255).collect();
    let lower: String = all.iter().map(|b| format!("{:02x}", b)).collect();
    let upper: String = all.iter().map(|b| format!("{:02X}", b)).collect();
    case("encode", &all, lower.as_bytes());
    case("encode_upper", &all, upper.as_bytes());
    case("decode", lower.as_bytes(), &all);
    case("decode", upper.as_bytes(), &all);
    case("round_trip", &all, &all);
    case(&format!("encode_to_slice {}", 2 * all.len()), &all, lower.as_bytes());
    case(&format!("decode_to_slice {}", all.len()), upper.as_bytes(), &all);
    for b in 0..=255u8 {
        if is_digit(b) {
            let text = [b'0', b];
            let v = u8::from_str_radix(std::str::from_utf8(&text).unwrap(), 16).unwrap();
            case("decode", &text, &[v]);
            let text = [b, b'0'];
            let v = u8::from_str_radix(std::str::from_utf8(&text).unwrap(), 16).unwrap();
            case("decode", &text, &[v]);
        } else {
            let c = b as char;
            let shown = format!("{:?}", c);
            let debug0 = format!("Err(InvalidHexCharacter {{ c: {}, index: 0 }})", shown);
            let debug1 = format!("Err(InvalidHexCharacter {{ c: {}, index: 1 }})", shown);
            let display = format!("Invalid character {:?} at position 0", c);
            case("decode", &[b, b'0'], debug0.as_bytes());
            case("decode", &[b'0', b], debug1.as_bytes());
            case("decode display", &[b, b'0'], display.as_bytes());
        }
    }
}
